// features/vendors.feature: "Vendors from another tenant are invisible"
// Note: the fixtures index asks AI assistants not to assert 404s or error codes for
// another tenant's data. This scenario explicitly specifies both, so the assertions
// below follow the scenario. Seeding the Globex vendor assumes a "globex" persona exists
// in ./fixtures/users; adjust the persona name if the seed data differs.
import { expect, expectStatus, test, uniqueName, type Persona } from "../fixtures";

test.describe("manage vendors", () => {
  test("vendors from another tenant are invisible", { tag: "@VEN-07" }, async ({ apiAs }) => {
    // Arrange: a vendor exists in tenant "Globex Procurement"
    const globex = await apiAs("globex" as Persona);
    const created = await globex.post("/api/vendors", {
      data: {
        name: uniqueName("Globex Vendor"),
        category: "services",
        contact_email: "ops@globex.test",
      },
    });
    const vendor = await expectStatus<{ id: string }>(created, 201);

    // Act: the Northwind member requests that vendor by id
    const member = await apiAs("member");
    const response = await member.get(`/api/vendors/${vendor.id}`);

    // Assert
    const body = await expectStatus<{ error: { code: string } }>(response, 404);
    expect(body.error.code).toBe("vendor_not_found");
  });
});
